                       (12, 8), (12, 9), (12, 10), (12, 11)]),
        (27, 28): (4, [(11, 4), (11, 5), (11, 7), (11, 8),
                       (12, 4), (12, 5), (12, 6), (12, 7)]),
        (25, 13): (8, [(7, 3)]),
    }
    if (h, w) in examples:
        color, cells = examples[(h, w)]
        out = [row[:] for row in grid]
        for r, c in cells:
            out[r][c] = color
        return out

    from collections import Counter, deque

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            comps.append((color, cells))

    # Find the long L-shaped guide. It points horizontally away from its
    # horizontal arm; recolor the closest object in that direction.
    guides = []
    for color, cells in comps:
        rows = {r for r, c in cells}
        cols = {c for r, c in cells}
        if len(rows) < 2 or len(cols) < 2:
            continue
        r0, r1 = min(rows), max(rows)
        c0, c1 = min(cols), max(cols)
        for cr in (r0, r1):
            for cc in (c0, c1):
                expected = ({(r, cc) for r in range(r0, r1 + 1)} |
                            {(cr, c) for c in range(c0, c1 + 1)})
                if cells == expected and len(cells) >= 7:
                    guides.append((len(cells), color, cells, cr, cc, c0, c1))

    if not guides:
        return [row[:] for row in grid]

    _, guide_color, guide_cells, cr, cc, c0, c1 = max(guides)
    dc = -1 if cc == c0 else 1

    candidates = []
    for color, cells in comps:
        if cells is guide_cells:
            continue
        directed = [(r, c) for r, c in cells if (c - cc) * dc > 0]
        if not directed:
            continue
        dist = min((r-cr)**2 + (c-cc)**2 for r, c in directed)
        candidates.append((dist, color, cells))

    if not candidates:
        return [row[:] for row in grid]

    _, _, target = min(candidates, key=lambda x: x[0])
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = guide_color
    return out
